changeSet.sql:
CREATE TABLE IF NOT EXISTS integration.amo_token ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), client_id TEXT, client_secret TEXT, redirect_uri TEXT, access_token TEXT, refresh_token TEXT, server_time BIGINT, expires_in BIGINT, token_type TEXT, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS integration.amo_contact ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), amo_contact_id BIGINT, name TEXT, first_name TEXT, last_name TEXT, phone TEXT, hesap_user_id UUID, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_amo_contact_hesap_user_id ON integration.amo_contact (hesap_user_id); CREATE INDEX IF NOT EXISTS idx_amo_token_created_date ON integration.amo_token (created_date DESC);
